// ***************
// Filename: uart_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of uart: joins the register map uart_regs
//   (modport regs) and the logic uart (modport core). cfg_* go from the
//   register map to the logic (register values, _wr write pulses, _rd read
//   pulses), sts_* come back (values read, _set / _clr hardware set / clear
//   pulses). A logic block ties every sts_* member it does not use to 0.
//   Generated by ip/scripts/regmap_gen.py from uart_regs.json: edit the JSON
//   and regenerate.
// Date: 2026-10-16
interface uart_regs_if ();
  logic [32-1:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [32-1:0] cfg_fcw;
  logic cfg_fcw_wr;
  logic [32-1:0] sts_status;
  logic [32-1:0] cfg_status;
  logic cfg_status_wr;
  logic [32-1:0] sts_err_cnt;

  modport regs (output cfg_ctrl, cfg_ctrl_wr, cfg_fcw, cfg_fcw_wr, cfg_status, cfg_status_wr, input
    sts_status, sts_err_cnt);
  modport core (output sts_status, sts_err_cnt, input cfg_ctrl, cfg_ctrl_wr, cfg_fcw, cfg_fcw_wr, cfg_status,
    cfg_status_wr);
  modport monitor (input cfg_ctrl, cfg_ctrl_wr, cfg_fcw, cfg_fcw_wr, cfg_status, cfg_status_wr, sts_status,
    sts_err_cnt);
endinterface
